import{_ as n,l as s,o,c as l,v as a,p as i,x as e,d as h,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Grok 4.5 / 4.6","description":"","frontmatter":{"title":"Grok 4.5 / 4.6","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grok-4-5.md","filePath":"llm/grok-4-5.md","lastUpdated":1789023840000}'),d={name:"llm/grok-4-5.md"};function k(A,r,g,c,B,u){const t=s("Mermaid");return o(),l("div",null,[r[1]||(r[1]=a('<h1 id="grok-4-5-4-6" tabindex="-1">Grok 4.5 / 4.6 <a class="header-anchor" href="#grok-4-5-4-6" aria-label="Permalink to &quot;Grok 4.5 / 4.6&quot;">​</a></h1><div class="epigraph"><p>Grok 4.5 按编码、智能体任务与知识工作来训，并与 Cursor 一起训练；4.6 在更长的补充训练之后，把重心放到长程智能体和更重的交互、视觉成品。</p><footer>—— xAI / SpaceXAI，Introducing Grok 4.5（2026-07-16）；Introducing Grok 4.6（2026-08-12）</footer></div><p><a href="/llm/grok-2-3">Grok-2 / Grok-3</a> 起，xAI 就只发产品博客与榜，不发与 <a href="/llm/grok-1">Grok-1</a> 同等级的结构表。<strong>Grok 4.5</strong>（2026 年 7 月 16 日）和大约五周后的 <strong>Grok 4.6</strong>（8 月 12 日）延续这条策略：能核对的是窗口、价、推理档、训练叙事和基准表；专家个数、层数、是否仍为 MoE，<strong>公开信息有限</strong>。两者都以编码 / 智能体 / 知识工作为主轴，并成为 Grok Build 与 Cursor 的默认档之一。本篇只整理官方新闻与开发者文档，不用 1 的 8 专家 top-2 去填 4.x。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Grok 3 把 Think 与 DeepSearch 做成推理智能体产品；到 2026 年夏天，竞品已经把「修仓库、写办公文档、在 IDE 里跑几十步工具」当成旗舰验收，而不只是 Arena 聊天。4.5 要解决的产品问题是：在<strong>不涨价</strong>的前提下，把智能体编码和知识工作推到可对标同期闭源旗舰的位置，并且服务速度按「快模型」来卖。4.6 则承认 4.5 在<strong>长轨迹</strong>和<strong>第一口视觉成品</strong>上仍不够：研究、跨仓修改、把模糊产品想法做成可迭代应用，需要模型在很多步之后仍盯着同一目标。</p><p>另一条约束是平台。模型绑在 xAI API、Grok Build、Cursor 以及 OpenRouter / Vercel / Cloudflare 一类网关上。评测必须写清 harness 与 <code>reasoning_effort</code>，否则 DeepSWE 与 Artificial Analysis 复合分会对不上。</p><h3 id="代际是产品名-不是开源版本号" tabindex="-1">代际是产品名，不是开源版本号 <a class="header-anchor" href="#代际是产品名-不是开源版本号" aria-label="Permalink to &quot;代际是产品名，不是开源版本号&quot;">​</a></h3><p>4.5 博客写「我们最强的模型」，强调与 Cursor 一起训练，服务约 <strong>80 TPS</strong>，并称在同类任务上大约 <strong>2×</strong> 的 token 效率（更少步数、更少输出 token）。4.6 不改价，明确写成 4.5 的后续：更长的补充训练、用 4.5 重写 SFT 轨迹、再做面向长程智能体的 RL。文档给 4.6 的窗口是 <strong>500,000</strong> token，知识截止公开为 2026 年 1 月（概览页）或 2 月 1 日（另一份模型页口径，引用应钉当时文档）。输入支持文本与图像，输出仅文本，无文本输出上限。不要把 Grok-1.5 的 128k 或后来某快照的窗口默认抄到 4.6。</p><p><span class="marginnote">4.5 / 4.6 的层数、词表、是否 MoE，官方新闻未给表。文中出现的 500k 窗口、低价缓存档、fast 变体「贵一倍」，都以开发者文档与 4.6 新闻为准，不能外推成架构分支。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>能写进方法的是<strong>训练与后训练的公开句子</strong>，不是网络图。</p><p>4.5：在数万块 NVIDIA GB300 上训练，强调去重、质量打分与领域筛选，而不是只报 token 总量（总量未公开）。强化学习覆盖数十万任务，中心是多步软件工程与其它技术工作，评分用自动与模型打分；栈被写成高度异步，智能体 rollout 可跑许多小时，同时学习在数万 GPU 上继续。这解释的是「为何能跟 Cursor 一起训」，不是一张并行切分图。</p><h3 id="_4-6-更长的补充跑-再用-4-5-当轨迹老师" tabindex="-1">4.6：更长的补充跑，再用 4.5 当轨迹老师 <a class="header-anchor" href="#_4-6-更长的补充跑-再用-4-5-当轨迹老师" aria-label="Permalink to &quot;4.6：更长的补充跑，再用 4.5 当轨迹老师&quot;">​</a></h3><p>4.6 新闻写：补充训练长于 4.5，数据含模型自生成的推理与高阶技术概念、高质量工程数据，以及改进的优化器与配方，从而给后续 SFT / RL 更好的底座。然后用 <strong>Grok 4.5 按不同推理力度、智能体 harness、STEM / 软件工程 / 知识工作域重生成 SFT 轨迹</strong>，再用模型检查滤掉有问题的痕迹。RL 覆盖知识工作、通用编码，以及内核优化、Web、CAD 等专用环境。安全句只有「防护按能力校准、部署前评测套件是迄今最宽」，没有系统卡级别的准备度表。</p>',14)),(o(),i(p,null,{default:e(()=>[E(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%95%B0%E6%8D%AE%E8%BF%87%E6%BB%A4%20%2F%20%E9%A2%86%E5%9F%9F%E9%85%8D%E6%AF%94%22%5D%20--%3E%20PRE%5B%22%E5%A4%A7%E8%A7%84%E6%A8%A1%E9%A2%84%E8%AE%AD%E7%BB%83%EF%BC%88%E6%80%BB%E9%87%8F%E6%9C%AA%E5%85%AC%E5%BC%80%EF%BC%89%22%5D%0A%20%20PRE%20--%3E%20RL45%5B%224.5%EF%BC%9A%E5%BC%82%E6%AD%A5%20RL%EF%BC%8C%E6%95%B0%E5%8D%81%E4%B8%87%E5%B7%A5%E7%A8%8B%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20RL45%20--%3E%20G45%5B%22Grok%204.5%22%5D%0A%20%20G45%20--%3E%20SYN%5B%22%E6%8C%89%20effort%20%2F%20harness%20%E9%87%8D%E5%86%99%20SFT%22%5D%0A%20%20SUP%5B%22%E6%9B%B4%E9%95%BF%E8%A1%A5%E5%85%85%E8%AE%AD%E7%BB%83%20%2B%20%E6%96%B0%E4%BC%98%E5%8C%96%E5%99%A8%E9%85%8D%E6%96%B9%22%5D%20--%3E%20SFT46%5B%224.6%20SFT%20%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20SYN%20--%3E%20SFT46%0A%20%20SFT46%20--%3E%20RL46%5B%22%E9%95%BF%E7%A8%8B%E6%99%BA%E8%83%BD%E4%BD%93%20RL%22%5D%0A%20%20RL46%20--%3E%20G46%5B%22Grok%204.6%22%5D%0A"})]),fallback:e(()=>[...r[0]||(r[0]=[h(" Loading... ",-1)])]),_:1})),r[2]||(r[2]=a('<p>定价两条新闻一致：每百万输入 <strong>2 美元</strong>、输出 <strong>6 美元</strong>；4.6 另有 fast 变体，价约为两倍。文档还给出缓存输入价，以及提示超过约 20 万 token 时输入 / 缓存 / 输出翻倍的档（以当时定价页为准）。推理力度：4.5 为 low / medium / high（默认 high）；4.6 增加 <strong>xhigh</strong>。工具：函数调用、网页搜索、X 搜索、代码执行。</p><p><span class="marginnote">4.6 新闻表：AA Intelligence Index 61（4.5 High 为 56，与 GPT-5.6 Sol Max 打平，Fable 5 Max 为 62）；CursorBench 3.2 为 69.9%；DeepSWE 1.1 为 65.9%。第三方分数取「自评或公开最好」，对照时必须写 effort 与 harness。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>从机制上能说的只有产品露出的那一层。500k 窗口把整段仓库、长报告和多步工具观察放进同一条件；没有公开注意力实现，就不能写是稠密、稀疏还是线性核。<code>reasoning_effort</code> 把测试时计算从「是否按 Think 按钮」收成 API 档位：low 换延迟，xhigh 换长轨迹质量。4.6 强调更强的自我测试与第一口视觉结构，这是后训练分布变了，不是证明内部换成了扩散头——输出仍是文本，应用与幻灯片是工具环画出来的。</p><p>Token 效率被 4.5 写成相对竞品大约一半步数、SWE-Bench Pro 上更少输出 token。这改变账单形状：同样 2 / 6 的标价，真正成本取决于模型会不会把简单题写成万 token 内心独白。强制 <code>prompt_cache_key</code>（或 Chat Completions 上的会话头）是为了把多轮打到同一机、让前缀缓存命中；长智能体环还要靠上下文压缩，否则 500k 会被工具 JSON 填满。</p><h3 id="算力口号不是架构" tabindex="-1">算力口号不是架构 <a class="header-anchor" href="#算力口号不是架构" aria-label="Permalink to &quot;算力口号不是架构&quot;">​</a></h3><p>「数万 GB300」「异步 rollout 许多小时」约束的是能花的 FLOP 与墙钟，不揭示总参与激活。把 4.6 理解成「参数比 4.5 大一号」没有根据；官方只说补充训练更长、配方更好。与 Cursor 合训解释的是数据与 harness 分布，不是 Cursor 内部有一份 Grok 权重。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>本篇最重要的边界是：<strong>没有技术报告</strong>。任何层宽、专家表、优化器名，若只出现在二手博客，应视为未证实。许可是专有 API 与产品条款，与 Grok-1 的 Apache 2.0 不是同一对象。评测应区分关闭联网的纯模型、打开搜索的智能体、high / xhigh 推理档。4.6 在 Terminal-Bench 3.0 上官方表为 26%，低于若干对照的三十多分——长程编码强、终端基准弱，不能用复合 Index 盖住。</p><p>工程上，fast 变体用钱换 TPS；不设缓存键会把输入价打满。图像可进、文本出，生图若走其它栈，安全策略不能混用。后续快照若改窗口或价，属于另一篇。</p><p><span class="marginnote">出处：SpaceXAI / xAI，<em>Introducing Grok 4.5</em>（2026-07-16）；<em>Introducing Grok 4.6</em>（2026-08-12）；开发者文档 <em>Grok 4.6</em> 概览。结构表公开信息有限。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Grok 4.5（2026-07-16）主打编码、智能体与知识工作，与 Cursor 合训，价 2 / 6，约 80 TPS，推理 low–high。</li><li>Grok 4.6（2026-08-12）加长补充训练，用 4.5 再生 SFT，强化长程智能体与视觉交互成品；窗口 500k，effort 含 xhigh，价不变，另有贵一倍的 fast 档。</li><li>不得用 Grok-1 的专家表填 4.x；基准必须写 effort 与 harness。</li><li>出处：上述官方新闻与 API 文档。不编参数量。</li></ul>',13))])}const _=n(d,[["render",k]]);export{f as __pageData,_ as default};
